package com.fasterxml.jackson.databind.cfg;

import com.fasterxml.jackson.annotation.JsonAutoDetect;
import com.fasterxml.jackson.annotation.PropertyAccessor;
import com.fasterxml.jackson.core.Base64Variant;
import com.fasterxml.jackson.core.io.Base64Variant;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.cfg.BaseSettings;
import com.fasterxml.jackson.databind.cfg.HandlerInstantiator;
import com.fasterxml.jackson.databind.cfg.PropertyNamingStrategy;
import com.fasterxml.jackson.databind.introspect.AnnotationIntrospector;
import com.fasterxml.jackson.databind.introspect.AnnotationIntrospectorPair;
import com.fasterxml.jackson.databind.introspect.ClassIntrospector;
import com.fasterxml.jackson.databind.introspect.VisibilityChecker;
import com.fasterxml.jackson.databind.jsontype.TypeResolverBuilder;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.type.TypeResolverBuilder;
import com.fasterxml.jackson.databind.util.StdDateFormat;
import java.io.*;
import java.math.*;
import java.text.DateFormat;
import java.util.*;
import java.util.Locale;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class BaseSettings_withDateFormat_TriageGen1Test {

    private ClassIntrospector _classIntrospector;
    private AnnotationIntrospector _annotationIntrospector;
    private VisibilityChecker<?> _visibilityChecker;
    private PropertyNamingStrategy _propertyNamingStrategy;
    private TypeFactory _typeFactory;
    private TypeResolverBuilder<?> _typeResolverBuilder;
    private HandlerInstantiator _handlerInstantiator;
    private Locale _locale;
    private TimeZone _timeZone;
    private Base64Variant _defaultBase64;
    private BaseSettings _baseSettings;

    @Before
    public void setUp() {
        _classIntrospector = mock(ClassIntrospector.class);
        _annotationIntrospector = mock(AnnotationIntrospector.class);
        _visibilityChecker = mock(VisibilityChecker.class);
        _propertyNamingStrategy = mock(PropertyNamingStrategy.class);
        _typeFactory = mock(TypeFactory.class);
        _typeResolverBuilder = mock(TypeResolverBuilder.class);
        _handlerInstantiator = mock(HandlerInstantiator.class);
        _locale = Locale.US;
        _timeZone = TimeZone.getDefault();
        _defaultBase64 = Base64Variant.of("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789+/");

        _baseSettings = new BaseSettings(
                _classIntrospector, _annotationIntrospector, _visibilityChecker, _propertyNamingStrategy, 
                _typeFactory, _typeResolverBuilder, null, _handlerInstantiator, _locale, _timeZone, _defaultBase64
        );
    }

    @Test
    public void testWithDateFormat_SameInstanceReturnsThis() {
        DateFormat df = mock(DateFormat.class);
        // We need a BaseSettings that already has this df to trigger the equality check
        BaseSettings existingSettings = new BaseSettings(
                _classIntrospector, _annotationIntrospector, _visibilityChecker, _propertyNamingStrategy, 
                _typeFactory, _typeResolverBuilder, df, _handlerInstantiator, _locale, _timeZone, _defaultBase64
        );

        BaseSettings result = existingSettings.withDateFormat(df);

        assertSame("Should return the same instance if DateFormat is identical", existingSettings, result);
    }

    @Test
    public void testWithDateFormat_NewInstanceWithDateFormat() {
        DateFormat df = mock(DateFormat.class);
        when(df.getTimeZone()).thenReturn(_timeZone);

        BaseSettings result = _baseSettings.withDateFormat(df);

        assertEquals("New settings should have the new DateFormat", df, result.getDateFormat());
        assertEquals("New settings should retain the same TimeZone from DateFormat", _timeZone, result.getTimeZone());
        assertSame("Should be a different instance", false, result == _baseSettings);
        // Verify other properties are copied
        assertEquals(_locale, result.getLocale());
        assertEquals(_typeFactory, result.getTypeFactory());
    }

    @Test
    public void testWithDateFormat_NullDateFormatUsesExistingTimeZone() {
        // Initial settings have _timeZone set in setUp
        BaseSettings result = _baseSettings.withDateFormat(null);

        assertEquals("DateFormat should be null", null, result.getDateFormat());
        assertEquals("TimeZone should fall back to existing TimeZone", _timeZone, result.getTimeZone());
        assertSame("Should be a different instance", false, result == _baseSettings);
    }

    @Test
    public void testWithDateFormat_NewDateFormatWithDifferentTimeZone() {
        DateFormat df = mock(DateFormat.class);
        TimeZone differentTz = TimeZone.getTimeZone("UTC");
        when(df.getTimeZone()).thenReturn(differentTz);

        BaseSettings result = _baseSettings.withDateFormat(df);

        assertEquals(df, result.getDateFormat());
        assertEquals(differentTz, result.getTimeZone());
    }
}
